events.command:
/usr/bin/bash -lc "set -e
find /workspace/final_answer -maxdepth 1 -type f -printf '%f\\n' | sort
awk -F '\\t' '
NR==1 {
  if ("'$1 != "gene") { print "bad pseudobulk first column" > "/dev/stderr"; exit 1 }
  ncols=NF-1
  for (i=2; i<=NF; i++) {
    if ($i == "" || $i ~ /[ -]/ || seen[$i]++) { print "bad pseudobulk column: " $i > "/dev/stderr"; exit 1 }
  }
  next
}
{
  if (NF != ncols+1 || $1 == "") { print "bad pseudobulk row " NR > "/dev/stderr"; exit 1 }
  for (i=2; i<=NF; i++) if ($i !~ /''^[0-9]+$/) { print "bad count at row " NR > "/dev/stderr"; exit 1 }
  rows++
}
END { print "pseudobulk rows=" rows ", samples=" ncols; if (rows != 1429 || ncols != 34) exit 1 }
'"' /workspace/final_answer/pseudobulk_counts.tsv
awk -F '\\t' '
NR==1 { if (NF "'!= 4 || $1 != "gene" || $2 != "log2_fold_change" || $3 != "p_value" || $4 != "fdr") { print "bad DE header" > "/dev/stderr"; exit 1 }; next }
{
  if (NF != 4 || $1 == "") { print "bad DE row " NR > "/dev/stderr"; exit 1 }
  if ($2 !~ /''^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$/ || ($2+0) != ($2+0)) { print "bad LFC at row " NR > "/dev/stderr"; exit 1 }
  if ($3 !~ /''^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$/ || ($3+0) != ($3+0) || ($3+0)<0 || ($3+0)>1) { print "bad p at row " NR > "/dev/stderr"; exit 1 }
  if ($4 !~ /''^[+-]?([0-9]+([.][0-9]*)?|[.][0-9]+)([eE][+-]?[0-9]+)?$/ || ($4+0) != ($4+0) || ($4+0)<0 || ($4+0)>1) { print "bad fdr at row " NR > "/dev/stderr"; exit 1 }
  rows++
}
END { print "DE rows=" rows; if (rows != 1429) exit 1 }
'"' /workspace/final_answer/differential_expression.tsv
comm -3 <(tail -n +2 /workspace/final_answer/pseudobulk_counts.tsv | cut -f1 | sort) <(tail -n +2 /workspace/final_answer/differential_expression.tsv | cut -f1 | sort) > /tmp/gene_set_difference
if test -s /tmp/gene_set_difference; then sed -n '1,20p' /tmp/gene_set_difference; exit 1; fi
jq -e 'keys == [\"method\"] and .method == \"DESeq2\"' /workspace/final_answer/method.json >/dev/null
printf 'gene sets identical; method.json valid\\n'"
